import{z as i,x as p,o,c as A,q as n,j as E,D as e,d as m,s,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"RMSNorm","description":"","frontmatter":{"title":"RMSNorm","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rmsnorm.md","filePath":"llm/rmsnorm.md","lastUpdated":1791413859000}'),d={name:"llm/rmsnorm.md"};function N(B,a,h,S,R,c){const t=p("Mermaid");return o(),A("div",null,[a[2]||(a[2]=n('<h1 id="rmsnorm" tabindex="-1">RMSNorm <a class="header-anchor" href="#rmsnorm" aria-label="Permalink to &quot;RMSNorm&quot;">​</a></h1><div class="epigraph"><p>不必减去均值；用均方根把向量拉到稳定尺度，层归一化就能又快又够用。</p><footer>—— Zhang 与 Sennrich，RMSNorm，2019</footer></div><p><a href="/llm/pre-ln-post-ln">上一课</a>把 LN 相对残差的位置写成稳定性：Pre-LN 留一条不经过子层的梯度公路，深层好训；Post-LN 输出尺度整齐，深了常训不成。顺序定了，块内部仍可以换算子。缺口是均值中心化这一步对 Transformer 是否必要。Zhang 与 Sennrich 2019 年的 RMSNorm 只除均方根，通常只留增益 \\(\\gamma\\)，LLaMA 之后的开源解码器几乎把它当成默认。本课写这个更便宜的尺度约束，不重推 Pre-LN 的梯度通路。它不是新的残差顺序，和 DeepNorm、并行 Attention-FFN 正交。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LayerNorm 对 \\(x\\in\\mathbb{R}^{d}\\) 计算</p> \\[\\mu=\\frac{1}{d}\\sum_j x_j,\\qquad \\sigma=\\sqrt{\\frac{1}{d}\\sum_j (x_j-\\mu)^2} \\]<p>再输出 \\(\\gamma\\odot(x-\\mu)/\\sigma+\\beta\\)。减均值让特征在超平面 \\(\\mathbf{1}^\\top y=0\\) 上，除 \\(\\sigma\\) 固定欧氏尺度。Transformer 里 \\(d\\) 已是隐层宽度，不存在 BatchNorm 那种随批量变化的统计。计算上，减均值要先扫一遍求和，再扫一遍方差，再仿射；在带宽紧的内核里，这两次归约会占去不可忽视的时间。</p><p><span class="marginnote">给 RMS 代个数字：\\(x=[3,4]\\) 时，\\(\\mathrm{RMS}(x)=\\sqrt{(3^2+4^2)/2}=\\sqrt{12.5}\\approx3.54\\)，归一后约 \\([0.85, 1.13]\\)，模长被拉回 \\(\\sqrt{2}\\approx1.41\\) 量级。注意它只动「音量旋钮」不挪「零点」——LayerNorm 还会先把向量减去均值 \\((3.5,3.5)\\) 再缩，两者输出的方向从此不同。</span></p><p>更关键的是功能：若模型真正需要的是「别让下一层的线性映射碰到巨大的范数」，尺度比中心更重要。均值中心化会丢掉与全维偏置等价的一个自由度，有时还与残差里已经学到的偏置成分打架。问题是：去掉 \\(\\mu\\)，只保留尺度约束，质量掉多少、速度换回多少？<span class="marginnote">RMSNorm 的设计意图不是「近似 LayerNorm」。它假设再中心化不是 Transformer 残差块的必要条件。若某任务确实依赖特征均值所编码的全局偏置，去掉 \\(\\mu\\) 会改变可表示函数类，而不是只改变数值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义均方根</p> \\[\\mathrm{RMS}(x)=\\sqrt{\\frac{1}{d}\\sum_{j=1}^{d} x_j^2+\\varepsilon} \\]<p>RMSNorm 为</p> \\[\\mathrm{RMSNorm}(x)=\\gamma\\odot\\frac{x}{\\mathrm{RMS}(x)} \\]<p>通常不再加 \\(\\beta\\)。\\(\\gamma\\in\\mathbb{R}^{d}\\) 可学习，初始化为 \\(1\\)。\\(\\varepsilon\\) 防止全零向量。它只保证 \\(\\|y\\|_2\\) 与 \\(\\gamma\\) 同量级，不保证 \\(\\sum y_j=0\\)。</p><p><span class="marginnote">\\(\\varepsilon\\) 是防除零的「地板」：若某 token 的激活几乎全零，\\(\\mathrm{RMS}(x)\\to 0\\)，直接除会把数值炸成无穷大。加一个小量（常见 \\(10^{-5}\\) 到 \\(10^{-6}\\)）垫在分母下就能避免；设太小则近零时噪声被放大，太大则所有向量都缩不到应有尺度，归一化形同虚设。</span></p><p>在 Transformer 里，把 Pre-LN 的 \\(\\mathrm{LN}\\) 全部换成 \\(\\mathrm{RMSNorm}\\) 即得到常见的 LLaMA 块。注意力与 FFN 的输入尺度被钉住，残差主干仍是未归一的求和。Zhang 与 Sennrich 在机器翻译等实验上显示，质量与 LayerNorm 接近，训练与推理更快。</p>',17)),(o(),E(l,null,{default:e(()=>[s(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E7%89%B9%E5%BE%81%E5%90%91%E9%87%8F%22%5D%20--%3E%20R%5B%22%E8%AE%A1%E7%AE%97%E5%9D%87%E6%96%B9%E6%A0%B9%22%5D%0A%20%20X%20--%3E%20D%5B%22%E9%99%A4%E4%BB%A5%E5%9D%87%E6%96%B9%E6%A0%B9%22%5D%0A%20%20R%20--%3E%20D%0A%20%20D%20--%3E%20G%5B%22%E4%B9%98%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20G%20--%3E%20Y%5B%22%E9%80%81%E5%85%A5%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%88%96%E5%89%8D%E9%A6%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[m("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("h3",{id:"去掉均值之后还剩什么",tabindex:"-1"},[m("去掉均值之后还剩什么 "),r("a",{class:"header-anchor",href:"#去掉均值之后还剩什么","aria-label":'Permalink to "去掉均值之后还剩什么"'},"​")],-1)),a[5]||(a[5]=r("p",null,"除以 RMS 等价于把向量投影到球面上再按 \\(\\gamma\\) 拉伸各轴。下一层的线性映射看到的是方向与按维相对幅度，而不是绝对模长。这足以稳定点积注意力的尺度：若 \\(q\\)、\\(k\\) 的输入范数被限制，\\(q^\\top k\\) 不会随残差流膨胀而线性膨胀。FFN 的第一层线性同样不会因输入范数暴涨而把激活推到饱和区之外毫无控制。",-1)),(o(),E(l,null,{default:e(()=>[s(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20RS%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%E8%8C%83%E6%95%B0%E9%9A%8F%E5%B1%82%E6%95%B0%E7%B4%AF%E7%A7%AF%E8%86%A8%E8%83%80%22%5D%20--%3E%20QK%5B%22q%E3%80%81k%20%E8%BE%93%E5%85%A5%E8%8C%83%E6%95%B0%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20QK%20--%3E%20DOT%5B%22%E7%82%B9%E7%A7%AF%20q%E1%B5%80k%20%E9%9A%8F%E4%B9%8B%E7%BA%BF%E6%80%A7%E8%86%A8%E8%83%80%22%5D%0A%20%20DOT%20--%3E%20SAT%5B%22softmax%20%E9%A5%B1%E5%92%8C%EF%BC%9A%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%BF%87%E5%BA%A6%E9%9B%86%E4%B8%AD%E6%88%96%E9%80%80%E5%8C%96%22%5D%0A%20%20NORM%5B%22RMSNorm%20%E6%8A%8A%E8%BE%93%E5%85%A5%E8%8C%83%E6%95%B0%E9%92%89%E5%9C%A8%E4%B8%8E%20%CE%B3%20%E5%90%8C%E9%87%8F%E7%BA%A7%22%5D%20--%3E%20OK%5B%22q%E1%B5%80k%20%E9%87%8F%E7%BA%A7%E5%8F%97%E6%8E%A7%22%5D%0A%20%20OK%20--%3E%20ST%5B%22softmax%20%E6%95%B0%E5%80%BC%E7%A8%B3%E5%AE%9A%EF%BC%8C%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%8F%AF%E5%AD%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[m(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比「投影到球面」：除以 RMS 相当于把所有向量先按到半径固定的球面上，只保留方向和各维的相对比例，再由 \\(\\gamma\\) 决定每一维「该多响」。下一层的线性层从此只见相对幅度、不见绝对大小——绝对大小正是残差流里最容易失控的东西。</span></p><p>未减均值意味着若 \\(x\\) 整体偏移，\\(y\\) 仍带这个偏移的方向。残差块可以沿全维常数方向累积「背景电位」。实践中 \\(\\gamma\\) 可以抑制某些维，网络不一定会让这个方向爆炸；但它确实比 LayerNorm 更信任残差流里的加性全局成分。</p><h3 id="计算与数值" tabindex="-1">计算与数值 <a class="header-anchor" href="#计算与数值" aria-label="Permalink to &quot;计算与数值&quot;">​</a></h3><p>实现只需一次平方和、一次开方、一次按维乘法，省掉减均值的依赖链，也省掉中心化后的第二次方差归约。混合精度下，RMS 在 fp16 里对大 \\(d\\) 可能溢出平方和，通常在 fp32 里归约再转回。\\(\\varepsilon\\) 过小会在近零激活时放大噪声，过大则等同给所有 token 加地板，削弱归一化。与 LayerNorm 相同，统计沿特征维，不沿 batch，因此对变长与小批量友好。</p><p><span class="marginnote">增益 \\(\\gamma\\) 不是可选项。没有 \\(\\gamma\\)，所有维被强迫同一 RMS，头与通道之间无法学「这一维该更响」。有人把 \\(\\gamma\\) 融进相邻线性层的权重，推理时可省一次逐元乘；训练时仍建议分开，便于与学习率解耦。</span></p><h3 id="与-layernorm-的可替换性" tabindex="-1">与 LayerNorm 的可替换性 <a class="header-anchor" href="#与-layernorm-的可替换性" aria-label="Permalink to &quot;与 LayerNorm 的可替换性&quot;">​</a></h3><p>在 Pre-LN 解码器、中等以上宽度上，二者常常可互换而不改其余超参，这是 RMSNorm 能成为默认的原因。但它们不是数学等价：LayerNorm 的输出正交于全 1 向量（仿射前），RMSNorm 不是。把 LayerNorm 训好的 \\(\\beta\\)、\\(\\gamma\\) 直接接到 RMSNorm 上没有意义。从 LayerNorm 模型蒸馏到 RMSNorm 需要重训归一化与相邻投影。编码器、极浅模型、或强依赖特征均值的探针任务上，差距可能放大，不能把解码器上的成功直接写成定理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RMSNorm 不解决 Pre-LN 与 Post-LN 的顺序问题，也不提供 DeepNet 那种随深度变化的残差增益。它只降低归一化本身的成本与一个约束。QK-Norm 若存在，通常也是对 \\(q\\)、\\(k\\) 做 RMS 或 LN，与块级 RMSNorm 叠床架屋时要避免重复压缩已经很小的向量。</p><p>与 BatchNorm 不同，RMSNorm 没有运行均值，推理与训练公式一致，这是它适合自回归解码的前提。序列长度不进入统计，长上下文不会让归一化统计「看见更多 token」——这既是优点（无长度泄漏），也意味着它不承担位置编码的职责。</p><p>在混合专家或并行 Attention-FFN 里，同一 \\(\\tilde x\\) 可能被多条分支读取。RMSNorm 只需算一次并广播，这比每条分支各做一遍 LayerNorm 更划算，但也意味着所有分支共享同一尺度。若某一专家希望自己的输入更尖或更平，不能指望归一化替它完成，必须写进专家权重。训练日志里应分别盯残差流范数与 RMS 输出范数：前者允许随层缓升，后者应大致钉在 \\(\\gamma\\) 的尺度上；若后者也暴涨，多半是 \\(\\varepsilon\\) 过小或 \\(\\gamma\\) 学习率过大，而不是「该换回 LayerNorm」的充分证据。</p><p><span class="marginnote">论文写于 2019 年，实验主体还不是千亿解码器。今日的默认地位来自后续开源模型的复用，而不是原文已经扫过所有尺度。换到新激活、新宽度或并行 Attention-FFN 时，仍应看梯度范数与损失尖峰，而不是假定 RMS 永远可插拔。</span></p><h3 id="何时仍用-layernorm" tabindex="-1">何时仍用 LayerNorm <a class="header-anchor" href="#何时仍用-layernorm" aria-label="Permalink to &quot;何时仍用 LayerNorm&quot;">​</a></h3><p>需要 \\(\\beta\\) 来表达特征均值、或与一批仍用 Post-LN LayerNorm 的检查点对齐时，保留 LayerNorm。教学与对照实验里也应保留，以免把「归一化」与「RMS」绑死。新模型默认 RMSNorm 是工程选择，不是 LayerNorm 被证伪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RMSNorm 用均方根缩放特征，不做均值中心化，通常只保留增益 \\(\\gamma\\)。</li><li>它稳定的是输入范数，从而稳定注意力点积与 FFN 的数值范围。</li><li>计算比 LayerNorm 少一次中心化归约，更易写成高速内核。</li><li>与 LayerNorm 函数类不同，不能无损热替换已训仿射参数。</li><li>不改变残差顺序，也不替代位置编码或残差缩放。</li><li>开源解码器的默认地位来自实践复用，原文提供的是方法与早期证据。</li><li>出处：Zhang 与 Sennrich，<em>Root Mean Square Layer Normalization</em>，2019；对照 Ba、Kiros、Hinton 的 LayerNorm（2016）以及 Xiong 等关于 LN 位置的讨论（2020）。</li></ul>',16))])}const u=i(d,[["render",N]]);export{f as __pageData,u as default};
